package com.minimarket.inventario.controller; import org.springframework.security.access.prepost.PreAuthorize;
import com.minimarket.common.ApiResponse; import com.minimarket.inventario.dto.*; import com.minimarket.inventario.service.InventarioService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/inventario") @RequiredArgsConstructor public class InventarioController{private final InventarioService s;@PostMapping("/movimientos")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('INVENTARIO_AJUSTAR')")
    public ApiResponse<InventarioResponseDTO> registrar(@Valid@RequestBody MovimientoInventarioRequest r){return ApiResponse.ok(s.registrar(r),"Movimiento registrado");}@GetMapping("/kardex/{productoId}")@PreAuthorize("hasAuthority('PRODUCTO_VER')")
    public ApiResponse<Page<InventarioResponseDTO>> kardex(@PathVariable Long productoId,Pageable p){return ApiResponse.ok(s.kardex(productoId,p));}}